async function fetchWithRateLimit(url) {
  const res = await fetch(url);
  if (res.status === 429) {
    const waitSec = parseInt(res.headers.get('Retry-After') || '1', 10);
    await new Promise(r => setTimeout(r, waitSec * 1000));
    return fetch(url);
  }
  return res;
}

